import {
  defineComponent,
  h,
  onBeforeUnmount,
  onMounted,
  onUpdated,
  shallowRef,
  watch,
  type Component,
  type PropType,
} from 'vue';
import {
  animate,
  createGeneratorEasing,
  generateLinearEasing,
  spring,
  supportsLinearEasing,
  type AnimationPlaybackControls,
  type Transition,
} from 'motion-v';
import { OTPInput as BaseOTPInput, type SlotProps } from 'vue-input-otp';

import {
  motionTokens,
  ReducedMotionConfig,
  toCssTiming,
  useMotionTokens,
  useReducedMotionSetting,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../utils/motion';

const SPRING: Transition = motionTokens.spring.glyph;
const RING_TRANSITION: Transition = motionTokens.spring.highlight;
const RING_FADE: Transition = motionTokens.transition.color;
const GHOST_TRANSITION: Transition = motionTokens.transition.popOut;
const GHOST_SCALE = 0.5;

const STAGGER = 0.05;

const LANDING = 0.05;
const LANDING_SCALE = 0.7;
const LANDING_OPACITY = 0.6;
const LANDING_ORIGIN = '50% 80%';

const CLEAR_STAGGER = 0.05;
const CLEAR_DROP = 6;

const WAVE_RISE = 4;
const WAVE_UP = 0.1;
const WAVE_DOWN: Transition = motionTokens.spring.checkPop;
const WAVE_STAGGER = 0.04;
const WAVE_AFTER = 0.12;
const WAVE_ID = 'animate-ui-otp-wave';

const SLOT_SELECTOR = '[data-slot="input-otp-slot"]';

function getEntry(prev: string, next: string) {
  let start = 0;
  while (
    start < prev.length &&
    start < next.length &&
    prev[start] === next[start]
  ) {
    start++;
  }
  let end = next.length;
  let prevEnd = prev.length;
  while (
    end > start &&
    prevEnd > start &&
    next[end - 1] === prev[prevEnd - 1]
  ) {
    end--;
    prevEnd--;
  }
  return { start, end };
}

const REDUCED_MOTION_CSS = `@media (prefers-reduced-motion:reduce){[data-input-otp-container]:not([data-full-motion]) ${SLOT_SELECTOR} *{animation:none!important}}[data-input-otp-container][data-reduced-motion] ${SLOT_SELECTOR} *{animation:none!important}`;

const running = new WeakMap<Element, Animation>();

const OVERLAY_STYLE = {
  position: 'absolute' as const,
  left: 0,
  top: 0,
  width: 0,
  height: 0,
  pointerEvents: 'none',
  zIndex: 10,
};
const RING_STYLE = {
  ...OVERLAY_STYLE,
  boxSizing: 'border-box',
  opacity: 0,
};

function springTiming(transition: Transition) {
  const { ease, duration } = createGeneratorEasing(transition, 100, spring);
  return {
    duration: duration * 1000,
    easing: supportsLinearEasing()
      ? generateLinearEasing(ease, duration * 1000)
      : 'ease-out',
  };
}

function translateOf(el: Element) {
  const [x = 0, y = 0] = getComputedStyle(el)
    .translate.split(' ')
    .map((part) => parseFloat(part) || 0);
  return { x, y };
}

type Box = { left: number; top: number; width: number; height: number };

function boxIn(container: HTMLElement, el: HTMLElement): Box {
  const outer = container.getBoundingClientRect();
  const rect = el.getBoundingClientRect();
  const scaleOf = (shown: number, laid: number) =>
    laid && Math.abs(shown - laid) >= 1 ? shown / laid : 1;
  const scaleX = scaleOf(outer.width, container.offsetWidth);
  const scaleY = scaleOf(outer.height, container.offsetHeight);
  const moved = translateOf(el);
  return {
    left: (rect.left - outer.left) / scaleX - container.clientLeft - moved.x,
    top: (rect.top - outer.top) / scaleY - container.clientTop - moved.y,
    width: rect.width / scaleX,
    height: rect.height / scaleY,
  };
}

const sameBox = (a: Box | null, b: Box) =>
  a !== null &&
  Math.abs(a.left - b.left) < 0.01 &&
  Math.abs(a.top - b.top) < 0.01 &&
  Math.abs(a.width - b.width) < 0.01 &&
  Math.abs(a.height - b.height) < 0.01;

const TEXT_PROPERTIES = [
  'fontFamily',
  'fontSize',
  'fontStyle',
  'fontWeight',
  'fontStretch',
  'fontKerning',
  'fontFeatureSettings',
  'fontVariationSettings',
  'fontVariantNumeric',
  'fontVariantLigatures',
  'fontVariantCaps',
  'fontOpticalSizing',
  'lineHeight',
  'letterSpacing',
  'wordSpacing',
  'textTransform',
  'textShadow',
  'color',
  'webkitTextFillColor',
  'webkitTextStrokeWidth',
  'webkitTextStrokeColor',
] as const;

function glyphCopy(container: HTMLElement, slot: HTMLElement, text: string) {
  const style = getComputedStyle(slot);
  const box = boxIn(container, slot);
  const copy = document.createElement('span');
  copy.textContent = text;
  Object.assign(copy.style, {
    position: 'absolute',
    left: `${box.left}px`,
    top: `${box.top}px`,
    width: `${box.width}px`,
    height: `${box.height}px`,
    boxSizing: 'border-box',
    borderStyle: 'solid',
    borderColor: 'transparent',
    borderTopWidth: style.borderTopWidth,
    borderRightWidth: style.borderRightWidth,
    borderBottomWidth: style.borderBottomWidth,
    borderLeftWidth: style.borderLeftWidth,
    paddingTop: style.paddingTop,
    paddingRight: style.paddingRight,
    paddingBottom: style.paddingBottom,
    paddingLeft: style.paddingLeft,
    display: style.display,
    flexDirection: style.flexDirection,
    alignItems: style.alignItems,
    justifyContent: style.justifyContent,
    textAlign: style.textAlign,
    whiteSpace: 'pre',
  });
  for (const property of TEXT_PROPERTIES)
    (copy.style as unknown as Record<string, string>)[property] = (
      style as unknown as Record<string, string>
    )[property]!;
  return copy;
}

function rideWave(slot: Element, el: Element) {
  for (const wave of slot.getAnimations()) {
    if (wave.id !== WAVE_ID) continue;
    const effect = wave.effect as KeyframeEffect;
    const ride = el.animate(effect.getKeyframes(), {
      ...(effect.getTiming() as KeyframeAnimationOptions),
      id: WAVE_ID,
      composite: 'add',
    });
    if (wave.startTime !== null) ride.startTime = wave.startTime;
    else ride.currentTime = wave.currentTime;
  }
}

function cancelWaves(el: Element) {
  for (const animation of el.getAnimations())
    if (animation.id === WAVE_ID) animation.cancel();
}

const RADII = [
  'borderTopLeftRadius',
  'borderTopRightRadius',
  'borderBottomRightRadius',
  'borderBottomLeftRadius',
] as const;

type Ring = { boxShadow: string; radii: string[] };

function takeRing(slot: HTMLElement): Ring {
  slot.style.removeProperty('box-shadow');
  const style = getComputedStyle(slot);
  const painted = style.boxShadow;
  const transition = shadowTransition(slot);
  const frames = transition
    ? (transition.effect as KeyframeEffect).getKeyframes()
    : null;
  const ring = frames ? String(frames.at(-1)!.boxShadow) : painted;
  const rest = frames ? String(frames[0]!.boxShadow) : 'none';
  transition?.cancel();
  if (ring !== 'none') {
    slot.style.boxShadow = rest;
    void getComputedStyle(slot).boxShadow;
    shadowTransition(slot)?.cancel();
  }
  return { boxShadow: ring, radii: RADII.map((corner) => style[corner]) };
}

function shadowTransition(slot: HTMLElement) {
  return slot
    .getAnimations()
    .find(
      (animation): animation is CSSTransition =>
        animation instanceof CSSTransition &&
        animation.transitionProperty === 'box-shadow',
    );
}

type RingState = {
  slot: HTMLElement | null;
  shown: boolean;
  box: Box | null;
  radii: string[];
  glide: AnimationPlaybackControls | null;
  fade: Animation | null;
};

const STYLE_ID = 'animate-ui-input-otp';

function injectStyle() {
  if (document.getElementById(STYLE_ID)) return;
  const style = document.createElement('style');
  style.id = STYLE_ID;
  style.textContent = REDUCED_MOTION_CSS;
  document.head.appendChild(style);
}

const SlotsMotion = defineComponent({
  name: 'InputOTPSlotsMotion',
  props: {
    slots: { type: Array as PropType<SlotProps[]>, required: true },
  },
  setup(props, { slots: children }) {
    const tokens = useMotionTokens();
    const tempo = () => tokens.value.tempo;
    const transition = useTempoTransition(() => SPRING);
    const ringTransition = useTempoTransition(() => RING_TRANSITION);
    const ringFade = useTempoTransition(() => RING_FADE);
    const ghostTransition = useTempoTransition(() => GHOST_TRANSITION);
    const waveDown = useTempoTransition(() => WAVE_DOWN);
    const reduce = useShouldReduceMotion();
    const setting = useReducedMotionSetting();
    const valueOf = () => props.slots.map((slot) => slot.char ?? '').join('');
    let prevValue = valueOf();
    let ringValue = prevValue;
    const ring = shallowRef<HTMLSpanElement | null>(null);
    const glyphs = shallowRef<HTMLSpanElement | null>(null);
    const ringState: RingState = {
      slot: null,
      shown: false,
      box: null,
      radii: [],
      glide: null,
      fade: null,
    };
    const leaving = new Map<HTMLElement, HTMLElement>();
    const entering = new Map<HTMLElement, HTMLElement>();

    const getContainer = () =>
      glyphs.value?.closest<HTMLElement>('[data-input-otp-container]') ??
      null;

    const placeRing = (
      box: Box,
      radii: string[],
      glide: boolean,
      delay = 0,
    ) => {
      const el = ring.value;
      const state = ringState;
      if (!el) return;
      state.glide?.stop();
      state.box = box;
      state.radii = radii;
      state.glide = animate(
        el,
        {
          left: `${box.left}px`,
          top: `${box.top}px`,
          width: `${box.width}px`,
          height: `${box.height}px`,
          ...Object.fromEntries(RADII.map((corner, i) => [corner, radii[i]])),
        },
        glide ? { ...ringTransition.value, delay } : { duration: 0 },
      );
    };

    const followRing = () => {
      const value = valueOf();
      const before = ringValue;
      ringValue = value;
      const container = getContainer();
      const el = ring.value;
      if (!container || !el) return;
      const state = ringState;
      const elements = Array.from(
        container.querySelectorAll<HTMLElement>(SLOT_SELECTOR),
      );
      const activeIndex = elements.findIndex(
        (slot) => slot.getAttribute('data-active') === 'true',
      );
      const typed =
        activeIndex > 0 &&
        state.slot === elements[activeIndex - 1] &&
        Boolean(value[activeIndex - 1]);
      const cleared =
        before.length - value.length > 1 && before.startsWith(value);
      const ringDelay = reduce.value
        ? 0
        : cleared
          ? (before.length - value.length) * CLEAR_STAGGER * tempo()
          : typed
            ? LANDING * tempo()
            : 0;
      const active = container.querySelector<HTMLElement>(
        `${SLOT_SELECTOR}[data-active="true"]`,
      );
      const moved = active !== state.slot;
      if (moved) {
        state.slot?.style.removeProperty('box-shadow');
        state.slot = active;
      }

      const fadeTo = (opacity: number) => {
        state.fade?.cancel();
        const from = getComputedStyle(el).opacity;
        el.style.opacity = String(opacity);
        const { duration, easing } = toCssTiming(ringFade.value);
        state.fade = el.animate([{ opacity: from }, { opacity }], {
          duration,
          easing,
        });
      };

      const worn = active ? takeRing(active) : null;
      if (!active || !worn || worn.boxShadow === 'none') {
        if (state.shown) fadeTo(0);
        state.shown = false;
        return;
      }
      el.style.boxShadow = worn.boxShadow;
      const box = boxIn(container, active);
      if (
        !moved &&
        state.shown &&
        sameBox(state.box, box) &&
        worn.radii.join() === state.radii.join()
      )
        return;
      placeRing(box, worn.radii, state.shown && !reduce.value, ringDelay);
      if (moved) {
        cancelWaves(el);
        rideWave(active, el);
      }
      if (!state.shown) fadeTo(1);
      state.shown = true;
    };

    const animateGlyphs = () => {
      const value = valueOf();
      const prev = prevValue;
      prevValue = value;
      if (prev === value) return;

      const container = getContainer();
      const layer = glyphs.value;
      if (!container || typeof Element.prototype.animate !== 'function') return;
      const elements = Array.from(
        container.querySelectorAll<HTMLElement>(SLOT_SELECTOR),
      );

      const cascade = prev.length - value.length > 1 && prev.startsWith(value);
      if (
        (!reduce.value || cascade) &&
        layer &&
        prev.length > value.length &&
        prev.startsWith(value)
      ) {
        const { duration, easing } = toCssTiming(ghostTransition.value);
        for (let index = value.length; index < prev.length; index++) {
          const slot = elements[index];
          if (!slot) continue;
          let from = { opacity: 1, scale: 1 };
          const growing = entering.get(slot);
          if (growing) {
            const style = getComputedStyle(growing);
            from = {
              opacity: Number(style.opacity),
              scale: style.scale === 'none' ? 1 : parseFloat(style.scale),
            };
            growing.remove();
            entering.delete(slot);
          }
          running.get(slot)?.cancel();
          leaving.get(slot)?.remove();
          if (from.opacity < 0.01) continue;
          const ghost = glyphCopy(container, slot, prev[index]!);
          ghost.dataset.glyph = 'leave';
          layer.append(ghost);
          leaving.set(slot, ghost);
          rideWave(slot, ghost);
          const shrink = cascade
            ? ghost.animate(
                [
                  {
                    opacity: from.opacity,
                    scale: from.scale,
                    translate: '0px 0px',
                    filter: 'blur(0px)',
                  },
                  {
                    opacity: 0,
                    scale: from.scale,
                    translate: `0px ${reduce.value ? 0 : CLEAR_DROP}px`,
                    filter: motionTokens.blur.surface,
                  },
                ],
                {
                  duration,
                  easing,
                  delay:
                    (prev.length - 1 - index) * CLEAR_STAGGER * tempo() * 1000,
                  fill: 'both',
                },
              )
            : ghost.animate(
                [
                  { opacity: from.opacity, scale: from.scale },
                  { opacity: 0, scale: Math.min(GHOST_SCALE, from.scale) },
                ],
                { duration, easing, fill: 'forwards' },
              );
          const done = () => {
            ghost.remove();
            if (leaving.get(slot) === ghost) leaving.delete(slot);
          };
          shrink.finished.then(done, done);
        }
      }

      for (const [slot, copy] of entering) {
        const index = elements.indexOf(slot);
        if (index !== -1 && copy.textContent === value[index]) continue;
        copy.remove();
        entering.delete(slot);
        running.get(slot)?.cancel();
      }

      const { start, end } = getEntry(prev, value);
      if (end <= start) return;
      for (let index = start; index < end; index++) {
        const slot = elements[index];
        if (!slot) continue;
        leaving.get(slot)?.remove();
        leaving.delete(slot);
      }

      const { duration, easing } = springTiming(transition.value);
      const stagger = !reduce.value && end - start > 1 ? STAGGER * tempo() : 0;

      for (let index = start; index < end; index++) {
        const el = elements[index];
        if (!el) continue;
        running.get(el)?.cancel();
        entering.get(el)?.remove();
        entering.delete(el);
        const delay = (index - start) * stagger * 1000;
        if (reduce.value || !layer) {
          const animation = el.animate([{ offset: 0, color: 'transparent' }], {
            duration,
            delay,
            easing,
            fill: 'backwards',
          });
          running.set(el, animation);
          continue;
        }
        const copy = glyphCopy(container, el, value[index]!);
        copy.dataset.glyph = 'enter';
        copy.style.transformOrigin = LANDING_ORIGIN;
        layer.append(copy);
        rideWave(el, copy);
        const opacity = Number(getComputedStyle(el).opacity);
        const landing = end - start === 1 ? LANDING * tempo() * 1000 : 0;
        if (landing)
          copy.animate(
            [
              { opacity: 0, scale: LANDING_SCALE * 0.8 },
              { opacity: opacity * LANDING_OPACITY, scale: LANDING_SCALE },
            ],
            { duration: landing / 2, easing: 'ease-out', fill: 'forwards' },
          );
        copy.animate(
          [
            landing
              ? { opacity: opacity * LANDING_OPACITY, scale: LANDING_SCALE }
              : { opacity: 0, scale: 0 },
            { opacity, scale: 1 },
          ],
          {
            duration,
            delay: delay + landing,
            easing,
            fill: landing ? 'forwards' : 'both',
          },
        );
        const hidden = el.animate(
          [
            {
              color: 'transparent',
              webkitTextFillColor: 'transparent',
              textShadow: 'none',
            },
            {
              color: 'transparent',
              webkitTextFillColor: 'transparent',
              textShadow: 'none',
            },
          ],
          { duration: duration + landing, delay, fill: 'backwards' },
        );
        running.set(el, hidden);
        entering.set(el, copy);
        const done = () => {
          copy.remove();
          if (entering.get(el) === copy) entering.delete(el);
        };
        hidden.finished.then(done, done);
      }

      if (
        reduce.value ||
        value.length < elements.length ||
        prev.length >= value.length
      )
        return;
      const up = WAVE_UP * tempo() * 1000;
      const down = springTiming(waveDown.value);
      const waveStart =
        ((end - start - 1) * stagger + WAVE_AFTER * tempo()) * 1000;
      const keyframes: Keyframe[] = [
        { translate: '0px 0px', easing: 'cubic-bezier(0.23, 1, 0.32, 1)' },
        {
          translate: `0px ${-WAVE_RISE}px`,
          offset: up / (up + down.duration),
          easing: down.easing,
        },
        { translate: '0px 0px' },
      ];
      const ringEl = ring.value;
      const ringSlot = ringState.slot;
      if (ringEl) cancelWaves(ringEl);
      elements.forEach((slot, index) => {
        cancelWaves(slot);
        const timing: KeyframeAnimationOptions = {
          id: WAVE_ID,
          duration: up + down.duration,
          delay: waveStart + index * WAVE_STAGGER * tempo() * 1000,
          composite: 'add',
        };
        slot.animate(keyframes, timing);
        for (const rider of [
          slot === ringSlot ? ringEl : null,
          entering.get(slot),
          leaving.get(slot),
        ]) {
          if (!rider) continue;
          cancelWaves(rider);
          rider.animate(keyframes, timing);
        }
      });
    };

    let observer: ResizeObserver | null = null;
    onMounted(() => {
      injectStyle();
      followRing();
      const container = getContainer();
      if (!container || typeof ResizeObserver === 'undefined') return;
      observer = new ResizeObserver(() => {
        const state = ringState;
        if (!state.shown || !state.slot) return;
        const box = boxIn(container, state.slot);
        if (!sameBox(state.box, box)) placeRing(box, state.radii, false);
      });
      observer.observe(container);
    });
    onUpdated(() => {
      followRing();
      animateGlyphs();
    });

    watch(
      [reduce, setting, glyphs],
      () => {
        const container = getContainer();
        container?.toggleAttribute('data-reduced-motion', reduce.value);
        container?.toggleAttribute(
          'data-full-motion',
          setting.value === 'never',
        );
      },
      { immediate: true, flush: 'post' },
    );

    onBeforeUnmount(() => {
      observer?.disconnect();
      ringState.slot?.style.removeProperty('box-shadow');
      ringState.slot = null;
      ringState.shown = false;
      ringState.box = null;
      leaving.forEach((ghost) => ghost.remove());
      leaving.clear();
      entering.forEach((copy, slot) => {
        copy.remove();
        running.get(slot)?.cancel();
      });
      entering.clear();
    });

    return () => [
      children.default?.(),
      h('span', {
        ref: glyphs,
        'aria-hidden': 'true',
        'data-slot': 'input-otp-ghosts',
        style: OVERLAY_STYLE,
      }),
      h('span', {
        ref: ring,
        'aria-hidden': 'true',
        'data-slot': 'input-otp-ring',
        style: RING_STYLE,
      }),
    ];
  },
});

/**
 * vue-input-otp's OTPInput, animated: typed characters spring in, deleted
 * ones shrink away and the focus ring glides from slot to slot.
 */
const OTPInput = defineComponent({
  name: 'OTPInput',
  inheritAttrs: false,
  setup(_, { attrs, slots }) {
    return () =>
      h(ReducedMotionConfig, null, () =>
        h(BaseOTPInput as Component, attrs, {
          default: (renderProps: { slots: SlotProps[] }) =>
            h(SlotsMotion, { slots: renderProps.slots }, () =>
              slots.default?.(renderProps),
            ),
        }),
      );
  },
});

export { OTPInput };
export {
  PublicVueOTPContextKey,
  REGEXP_ONLY_CHARS,
  REGEXP_ONLY_DIGITS,
  REGEXP_ONLY_DIGITS_AND_CHARS,
  useVueOTPContext,
  type OTPInputEmits,
  type OTPInputProps,
  type RenderProps,
  type SlotProps,
} from 'vue-input-otp';

import {
  computed,
  defineComponent,
  Fragment,
  getCurrentInstance,
  h,
  inject,
  onBeforeUnmount,
  onMounted,
  ref,
  type ComputedRef,
  type InjectionKey,
  type Ref,
} from 'vue';
import {
  createGeneratorEasing,
  generateLinearEasing,
  MotionConfig,
  spring as springGenerator,
  useMotionConfig,
  type Transition,
} from 'motion-v';

const ease = {
  out: [0.23, 1, 0.32, 1],
  soft: [0.215, 0.61, 0.355, 1],
  draw: [0, 0, 0.58, 1],
  inOut: [0.77, 0, 0.175, 1],
  away: [0.33, 0.17, 0.67, 0.5],
  in: [0.4, 0, 1, 1],
  drawer: [0.34, 1.2, 0.64, 1],
  arrive: [0.11, 0, 0.5, 0],
  color: [0.25, 0.1, 0.25, 1],
  leave: [0, 0, 0.58, 1],
  enter: [0.25, 0.1, 0.35, 1],
  resize: [0.4, 0, 0.1, 1],
  fill: [0.4, 0, 0.2, 1],
} as const;

const spring = {
  press: { type: 'spring', stiffness: 550, damping: 30, restSpeed: 10 },
  pop: { type: 'spring', stiffness: 400, damping: 29 },
  tooltip: { type: 'spring', stiffness: 400, damping: 31 },
  dialog: { type: 'spring', stiffness: 150, damping: 25 },
  toast: { type: 'spring', stiffness: 280, damping: 24 },
  selection: { type: 'spring', stiffness: 300, damping: 30 },
  highlight: { type: 'spring', stiffness: 500, damping: 40 },
  reflow: { type: 'spring', stiffness: 500, damping: 40 },
  handoff: { type: 'spring', stiffness: 450, damping: 43 },
  morph: { type: 'spring', stiffness: 660, damping: 52 },
  height: {
    type: 'spring',
    stiffness: 300,
    damping: 30,
    bounce: 0,
    restDelta: 0.01,
  },
  slide: { type: 'spring', stiffness: 300, damping: 35, restDelta: 0.01 },
  thumb: { type: 'spring', stiffness: 300, damping: 25 },
  slider: { type: 'spring', stiffness: 400, damping: 32 },
  bounce: { type: 'spring', stiffness: 200, damping: 16 },
  glyph: { type: 'spring', stiffness: 500, damping: 45 },
  checkPop: { type: 'spring', stiffness: 500, damping: 24 },
  entrance: { type: 'spring', stiffness: 200, damping: 20 },
  progress: {
    type: 'spring',
    stiffness: 300,
    damping: 35,
    restDelta: 0.01,
    restSpeed: 0.1,
  },
  number: { type: 'spring', stiffness: 90, damping: 50 },
} as const satisfies Record<string, Transition>;

const transition = {
  menu: { duration: 0.22, ease: ease.soft },
  overlay: { duration: 0.4, ease: ease.soft },
  dialogFade: { duration: 0.4, ease: ease.soft },
  fade: { duration: 0.2, ease: ease.out },
  color: { duration: 0.2, ease: ease.color },
  reveal: { duration: 0.3, ease: ease.out },
  disclosure: { duration: 0.35, ease: ease.soft },
  panelOut: { duration: 0.15, ease: ease.leave },
  panelIn: { duration: 0.3, ease: ease.enter },
  tooltipIn: { duration: 0.34, ease: ease.enter },
  tooltipOut: { duration: 0.13, ease: ease.leave },
  panelHeight: { duration: 0.45, ease: ease.resize },
  check: { duration: 0.3, delay: 0.2, ease: ease.draw },
  uncheck: { duration: 0.3, ease: ease.draw },
  fill: { duration: 0.3, ease: ease.fill },
  popOut: { duration: 0.15, ease: ease.out },
  swap: { duration: 0.15, ease: ease.out },
  spin: { duration: 0.3, ease: ease.out },
  handoffOut: { duration: 0.22, ease: ease.soft },
  handoffIn: { duration: 0.26, ease: ease.arrive },
  dismiss: { duration: 0.2, ease: ease.away },
  shake: { duration: 0.4, ease: ease.inOut },
  drawerOut: { duration: 0.16, ease: ease.in },
  drawer: { duration: 0.4, ease: ease.drawer },
  sheet: { duration: 0.4, ease: ease.soft },
  collapse: { duration: 0.28, ease: ease.inOut },
  collapseLabel: { duration: 0.14, ease: ease.out },
  instant: { duration: 0 },
} as const satisfies Record<string, Transition>;

const scale = {
  press: 0.97,
  choice: 0.985,
  tooltip: 0.7,
  popover: 0.8,
  menu: 0.9,
  dialog: 0.8,
  icon: 0.5,
  toast: 0.96,
  fill: 0.7,
  action: 0.9,
} as const;

const blur = {
  icon: 'blur(2px)',
  tooltip: 'blur(6px)',
  disclosure: 'blur(2px)',
  surface: 'blur(4px)',
  panel: 'blur(5px)',
} as const;

const rotate = {
  icon: 90,
} as const;

const shift = {
  handoff: 6,
  navigation: 24,
  tabs: 12,
  step: 24,
  tooltip: 40,
  shake: 3,
} as const;

const stagger: { readonly stack: number } = {
  stack: 0.03,
};

const TIME_KEYS = [
  'duration',
  'visualDuration',
  'delay',
  'repeatDelay',
  'delayChildren',
];

function scaleTransition<T extends Transition | undefined>(
  value: T,
  tempo: number,
): T {
  if (!value || tempo === 1 || typeof value !== 'object') return value;
  const scaled: Record<string, unknown> = {};
  for (const [key, part] of Object.entries(value)) {
    if (typeof part === 'number' && TIME_KEYS.includes(key))
      scaled[key] = part * tempo;
    else if (typeof part === 'number' && key === 'stiffness')
      scaled[key] = part / (tempo * tempo);
    else if (typeof part === 'number' && key === 'damping')
      scaled[key] = part / tempo;
    else if (part && typeof part === 'object' && !Array.isArray(part))
      scaled[key] = scaleTransition(part as Transition, tempo);
    else scaled[key] = part;
  }
  return scaled as T;
}

function createMotionTokens(tempo = 1) {
  const pace = <T extends Record<string, Transition>>(set: T): T =>
    tempo === 1
      ? set
      : (Object.fromEntries(
          Object.entries(set).map(([role, value]) => [
            role,
            scaleTransition(value, tempo),
          ]),
        ) as T);

  return {
    tempo,
    ease,
    scale,
    blur,
    rotate,
    shift,
    stagger:
      tempo === 1
        ? stagger
        : (Object.fromEntries(
            Object.entries(stagger).map(([role, delay]) => [
              role,
              delay * tempo,
            ]),
          ) as typeof stagger),
    spring: pace(spring),
    transition: pace(transition),
  } as const;
}

type MotionTokens = ReturnType<typeof createMotionTokens>;
type CheckAnimation = 'draw' | 'pop';
type ReducedMotion = 'user' | 'never' | 'always';

const motionTokens: MotionTokens = createMotionTokens();

const MotionTokensKey: InjectionKey<Ref<MotionTokens>> = Symbol(
  'AnimateUIMotionTokens',
);
const CheckAnimationKey: InjectionKey<Ref<CheckAnimation>> = Symbol(
  'AnimateUICheckAnimation',
);
const ReducedMotionKey: InjectionKey<Ref<ReducedMotion>> = Symbol(
  'AnimateUIReducedMotion',
);

function useMotionTokens(): Ref<MotionTokens> {
  return inject(MotionTokensKey, ref(motionTokens) as Ref<MotionTokens>);
}

/** Scales a transition by the provider's `tempo`. */
function useTempoTransition<T extends Transition | undefined>(
  value: () => T,
): ComputedRef<T> {
  const tokens = useMotionTokens();
  return computed(() => scaleTransition(value(), tokens.value.tempo));
}

function useCheckAnimation(own?: () => CheckAnimation | undefined) {
  const inherited = inject(CheckAnimationKey, ref<CheckAnimation>('draw'));
  return computed(() => own?.() ?? inherited.value);
}

function useReducedMotionSetting(): ComputedRef<ReducedMotion> {
  const own = inject(ReducedMotionKey, ref<ReducedMotion>('user'));
  const config = useMotionConfig();
  return computed(() =>
    config.value.reducedMotion === 'always' ? 'always' : own.value,
  );
}

type CssTiming = { duration: number; easing: string };

const CSS_EASINGS: Record<string, string> = {
  linear: 'linear',
  easeIn: 'cubic-bezier(0.42, 0, 1, 1)',
  easeOut: 'cubic-bezier(0, 0, 0.58, 1)',
  easeInOut: 'cubic-bezier(0.42, 0, 0.58, 1)',
  circIn: 'cubic-bezier(0, 0.65, 0.55, 1)',
  circOut: 'cubic-bezier(0.55, 0, 1, 0.45)',
  backIn: 'cubic-bezier(0.31, 0.01, 0.66, -0.59)',
  backOut: 'cubic-bezier(0.33, 1.53, 0.69, 0.99)',
};

const SPRING_KEYS = [
  'stiffness',
  'damping',
  'mass',
  'bounce',
  'visualDuration',
];

function toCssEase(curve: unknown): string {
  if (
    Array.isArray(curve) &&
    curve.length === 4 &&
    curve.every(Number.isFinite)
  )
    return `cubic-bezier(${curve.join(', ')})`;
  if (typeof curve === 'string') return CSS_EASINGS[curve] ?? 'ease';
  return CSS_EASINGS.easeInOut!;
}

function toCssTiming(motionTransition: Transition): CssTiming {
  const options = motionTransition as Record<string, unknown>;
  const isSpring =
    options.type === 'spring' || SPRING_KEYS.some((key) => key in options);

  if (isSpring) {
    const springOptions =
      typeof options.duration === 'number'
        ? { ...options, duration: options.duration * 1000 }
        : options;
    const { duration, ease: curve } = createGeneratorEasing(
      springOptions,
      100,
      springGenerator,
    );
    const ms = Math.round(duration * 1000);
    return { duration: ms, easing: generateLinearEasing(curve, ms) };
  }

  const seconds = typeof options.duration === 'number' ? options.duration : 0.3;
  return {
    duration: Math.round(seconds * 1000),
    easing: toCssEase(options.ease),
  };
}

const REDUCED_MOTION_QUERY = '(prefers-reduced-motion: reduce)';

// Once the app has mounted (hydrated), later components read the setting at once.
const appMounted = () =>
  Boolean(
    (
      getCurrentInstance()?.appContext.app as
        { _container?: unknown } | undefined
    )?._container,
  );

/** False on the server and while hydrating, then follows the OS setting. */
function useShouldReduceMotion(): ComputedRef<boolean> {
  const setting = useReducedMotionSetting();
  const prefersReduced = ref(
    appMounted() && window.matchMedia(REDUCED_MOTION_QUERY).matches,
  );
  let query: MediaQueryList | undefined;
  const update = () => {
    prefersReduced.value = query?.matches ?? false;
  };
  onMounted(() => {
    query = window.matchMedia(REDUCED_MOTION_QUERY);
    update();
    query.addEventListener('change', update);
  });
  onBeforeUnmount(() => query?.removeEventListener('change', update));
  return computed(() => {
    if (setting.value === 'never') return false;
    return setting.value === 'always' || prefersReduced.value;
  });
}

const RemountOnReduce = defineComponent({
  name: 'RemountOnReduce',
  setup(_, { slots }) {
    const reduce = useShouldReduceMotion();
    return () =>
      h(Fragment, { key: reduce.value ? 'reduce' : 'full' }, slots.default?.());
  },
});

const ReducedMotionConfig = defineComponent({
  name: 'ReducedMotionConfig',
  props: { remount: Boolean },
  setup(props, { slots }) {
    const reducedMotion = useReducedMotionSetting();
    return () =>
      h(MotionConfig, { reducedMotion: reducedMotion.value }, () =>
        props.remount ? h(RemountOnReduce, null, slots) : slots.default?.(),
      );
  },
});

export {
  createMotionTokens,
  motionTokens,
  MotionTokensKey,
  CheckAnimationKey,
  ReducedMotionKey,
  useMotionTokens,
  useCheckAnimation,
  ease,
  spring,
  transition,
  scale,
  blur,
  rotate,
  shift,
  stagger,
  ReducedMotionConfig,
  useShouldReduceMotion,
  useReducedMotionSetting,
  scaleTransition,
  toCssTiming,
  useTempoTransition,
  type CssTiming,
  type MotionTokens,
  type CheckAnimation,
  type ReducedMotion,
};
